function pairWithSum(sorted: number[], target: number): [number, number] | null {
  let left = 0
  let right = sorted.length - 1
  while (left < right) {
    const sum = sorted[left] + sorted[right]
    if (sum === target) return [left, right]
    if (sum < target) left++
    else right--
  }
  return null
}

