def pair_with_sum(sorted_list, target):
    left, right = 0, len(sorted_list) - 1
    while left < right:
        total = sorted_list[left] + sorted_list[right]
        if total == target:
            return left, right
        if total < target:
            left += 1
        else:
            right -= 1
    return None
